package org.achievementlabs.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.hardware.Camera;import android.view.*;import android.widget.*;
import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import com.google.zxing.qrcode.QRCodeReader;import java.util.concurrent.*;
public final class ScanActivity extends Activity implements SurfaceHolder.Callback,Camera.PreviewCallback {
 Camera camera;SurfaceView surface;TextView label;Core.Collector collector=new Core.Collector();ExecutorService worker=Executors.newSingleThreadExecutor();volatile boolean decoding,stopped;long last;boolean complete;
 @Override public void onCreate(Bundle b){super.onCreate(b);collector=new Core.Collector(getIntent().getBooleanExtra("queueOnly",false));LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(16,24,16,16);label=new TextView(this);label.setText("Point the camera at the looping PC codes. Keep these private.");label.setTextSize(18);root.addView(label);surface=new SurfaceView(this);root.addView(surface,new LinearLayout.LayoutParams(-1,0,1));Button reset=new Button(this);reset.setText("Reset scanner");reset.setOnClickListener(v->{collector=new Core.Collector(getIntent().getBooleanExtra("queueOnly",false));label.setText("Scanner reset.");});root.addView(reset);Button cancel=new Button(this);cancel.setText("Cancel");cancel.setOnClickListener(v->finish());root.addView(cancel);setContentView(root);surface.getHolder().addCallback(this);if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.CAMERA},10);}
 @Override public void onRequestPermissionsResult(int request,String[] p,int[] grants){super.onRequestPermissionsResult(request,p,grants);if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)open();else label.setText("Camera permission is required. Enable it in Android app settings.");}
 void open(){if(stopped||camera!=null||checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||!surface.getHolder().getSurface().isValid())return;try{camera=Camera.open();Camera.Parameters p=camera.getParameters();if(p.getSupportedFocusModes().contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);camera.setParameters(p);camera.setDisplayOrientation(90);camera.setPreviewDisplay(surface.getHolder());camera.setPreviewCallback(this);camera.startPreview();}catch(Exception e){label.setText("Camera unavailable. Close other camera apps and try again.");}}
 @Override public void surfaceCreated(SurfaceHolder h){open();}@Override public void surfaceChanged(SurfaceHolder h,int f,int w,int y){}@Override public void surfaceDestroyed(SurfaceHolder h){release();}
 @Override public void onPreviewFrame(byte[] data,Camera c){if(stopped||decoding||complete||System.currentTimeMillis()-last<100)return;decoding=true;last=System.currentTimeMillis();Camera.Size size=c.getParameters().getPreviewSize();byte[] copy=data.clone();worker.execute(()->{String result=null;try{result=new QRCodeReader().decode(new BinaryBitmap(new HybridBinarizer(new PlanarYUVLuminanceSource(copy,size.width,size.height,0,0,size.width,size.height,false)))).getText();}catch(Exception ignored){}String value=result;runOnUiThread(()->{try{if(value!=null&&!complete&&!stopped){org.json.JSONObject p=collector.add(value);label.setText(collector.progress());if(p!=null){complete=true;MainActivity.pendingQR=p;setResult(RESULT_OK);finish();}}}catch(Exception e){label.setText(e.getMessage());}finally{decoding=false;}});});}
 void release(){if(camera!=null){camera.setPreviewCallback(null);camera.stopPreview();camera.release();camera=null;}}
 @Override protected void onResume(){super.onResume();stopped=false;if(surface!=null)open();}@Override protected void onPause(){stopped=true;release();super.onPause();}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}

